// Helper function to map mal number to topic
function malToTopic(mal: number): LinuxExam510Topic {
    if (mal === 1) return 'troubleshooting';
    if (mal === 2) return 'storage-fhs-lvm';
    if (mal === 3) return 'permissions';
    if (mal === 4) return 'system-config';
    if (mal === 5) return 'networking';
    if (mal === 6) return 'backup';
    if (mal === 7) return 'docker';
    if (mal === 8) return 'git';
    if (mal >= 9 && mal <= 11) return 'server-ssh';
    if (mal >= 12 && mal <= 13) return 'bash';
    return 'yaml-json-integration'; // Mål 14-20
}

// Add topic to all questions based on mal number
const addTopicToQuestions = (questions: BaseLinuxExam510Question[]): LinuxExam510Question[] => {
    return questions.map(q => ({
        ...q,
        topic: malToTopic(q.mal)
    }));
};

export const ALL_LINUX_EXAM_510_QUESTIONS: LinuxExam510Question[] = [
    ...addTopicToQuestions(TROUBLESHOOTING_QUESTIONS),
    ...addTopicToQuestions(STORAGE_FHS_LVM_QUESTIONS),
    ...addTopicToQuestions(PERMISSIONS_QUESTIONS),
    ...addTopicToQuestions(SYSTEM_CONFIG_QUESTIONS),
    ...addTopicToQuestions(NETWORKING_QUESTIONS),
    ...addTopicToQuestions(BACKUP_QUESTIONS),
    ...addTopicToQuestions(DOCKER_QUESTIONS),
    ...addTopicToQuestions(GIT_QUESTIONS),
    ...addTopicToQuestions(SERVER_SSH_QUESTIONS),
    ...addTopicToQuestions(BASH_QUESTIONS),
    ...addTopicToQuestions(YAML_JSON_INTEGRATION_QUESTIONS),
];

// Get questions filtered by topics
export function getLinuxExam510QuestionsByTopics(selectedTopics: LinuxExam510Topic[]): LinuxExam510Question[] {
    return ALL_LINUX_EXAM_510_QUESTIONS.filter(q => selectedTopics.includes(q.topic));
}

// Helper function to convert to tenta-simulator format
export function getLinuxExam510Questions() {
    return ALL_LINUX_EXAM_510_QUESTIONS.map(q => ({
        id: q.id,
        question: q.question,
        options: q.options,
        correctIndex: q.correctIndex,
        explanation: q.explanation,
        difficulty: q.difficulty,
        category: q.category,
        topic: q.topic,
    }));
}

export default ALL_LINUX_EXAM_510_QUESTIONS;
